    "note": "日経平均は893.23円安の62,188.63円と3日続落した。始値62,973.16円、高値63,105.47円。米中間選挙の開票速報で民主党が上下両院で過半数を取る見通しと伝わると、トランプ政権の政策推進力低下とAI規制強化観測が浮上し、「AIデータセンター建設が中期的に停滞しかねない」との懸念からAI・半導体関連に売りが集中。後場には安値60,030.10円（一時3,000円超安、下落率一時約−4.84%）まで洗われ6万円割れ寸前に迫った。ただしトランプ大統領が選挙結果を受け入れる意向を示したと伝わると後場後半に下げ幅を急速に縮め、終値は高値圏で引けた。日経平均VIは40.30まで急騰したあと24.98（−30.07%）へ急低下した。業種別は33業種中8業種上昇・25業種下落で、上昇トップは空運業（+3.83%）、以下不動産業（+1.57%）、その他製品（+1.02%）、陸運業（+1.00%）、卸売業（+0.92%）。下落は非鉄金属（−4.88%）、石油・石炭製品（−4.39%）、鉱業（−4.02%）、電気機器（−2.40%）、ガラス・土石製品（−2.30%）の順で、売りはAI・半導体と商品関連に偏った。寄与度の押し下げはアドバンテスト−258.90円、東京エレクトロン−172.93円、ソフトバンクグループ−114.08円、京セラ−65.26円、フジクラ−44.50円で、上位4銘柄だけで約611円分を削った。押し上げはファーストリテイリング+162.62円、三菱商事+38.03円、日東電工+18.37円、ヤマトホールディングス+7.65円、任天堂+6.88円。TOPIXは34.90ポイント安の3,895.38（−0.89%）で日経平均より下落率は小さく、東証プライムの売買代金は概算10兆8,055億円、売買高は35億1,279万株と大商い。値上がり425・値下がり1,084・変わらず43で、全体の約7割が下落した。為替は方向感が二転した。ドル円は朝方の158円74銭を高値に、米中間選挙を受けた米長期金利の低下（米10年債利回りが一時4.89%）とリスク回避の円買いで157円41銭まで約1円30銭下落。ただし材料が織り込まれると米10年債利回りが4.93〜4.94%へ反発し、日経平均が6万円台を維持して下げ幅を縮めたことで円買いが一巡、株式大引け時点は158円04銭（前日NY終値比65銭の円高）まで戻した。日銀公表の午後5時時点は158円07〜09銭で前日比33銭のドル高・円安（基準の違いで符号が逆になる点に注意）。ユーロ円は177円15銭〜177円82銭のレンジで大引け177円57銭、午後5時時点177円65〜69銭（前日比1円04銭の円安）。レポート作成時点で入手できる最新は17時のドル円158円07銭、ユーロ円177円66銭、ユーロドル1.1239ドル（当日高値1.1263ドルは10月16日以来の水準）で、18時台も158円台前半での小動きが続いた。もっとも当日の報道はいずれも因果を「株安→円買い」の方向で説明しており、円高が輸出関連・半導体株の重荷になったとする解説は見られない。アドバンテスト、東京エレクトロン、キオクシア、レーザーテックなどの下落はあくまで中間選挙によるAI規制強化・データセンター投資停滞懸念に帰されている。一方で小売業（+0.63%）、卸売業（+0.92%）、陸運業（+1.00%）、不動産業（+1.57%）といった内需セクターは逆行高したが、これを円高による輸入コスト低下と結び付けた当日の報道も確認できなかった。日本国債は新発10年が2.810%（+0.040）へ上昇した。ストップ高は7銘柄、ストップ安は1銘柄（いずれも気配・一時ストップを含む株探基準）。"
