        "biz": "世界首位級の自動車メーカーで国内シェアも高い。ハイブリッドを中心とする環境技術に優位性を持ち「トヨタ」「レクサス」などのブランドを展開。車両の生産・販売に加え販売金融事業も手掛け、他社との提携を加速している。",
        "detail": "11月5日13時55分、27年3月期の営業利益を3兆4000億→3兆9000億円（14.7%増額）、経常益を4兆5700億→4兆9600億円、最終益を3兆2500億→3兆5700億円（9.8%増額）へ上方修正した。営業収益のみ54兆→53.5兆円に減額し想定為替を1ドル160円→157円に見直した。年間配当100円は据え置き。同時に自己株取得枠を5億株・1兆円から6億1000万株（自己株除く発行済の5.18%）・1兆3000億円へ拡大し、1株2,725円で約1億875万株・約2,963.6億円の自己株TOB（買付期間11月6日〜12月7日）も発表した。午前は米中間選挙で民主党が両院を制しトランプ政権の通商強硬姿勢が後退するとの思惑で自動車株が買われており、後場の発表で上げ幅を拡大して高値引け。上期は営業収益26.96兆円（9.5%増）、最終益2.24兆円（26.1%増）。",
        "outlook": "増額修正と自己株TOB（11月6日〜12月7日）で需給面の支えが続く一方、1日で16%超高した反動と、TOB価格2,725円が終値3,533円を大きく下回る点には注意が必要。損保などの政策保有株解消売りの出方、円相場、米通商政策を巡る報道が焦点。"
