        "detail": "11月5日に同社固有の開示はなく、下落はマクロ要因。直近の決算発表は10月28日引け後で、27年3月期を今期2度目の上方修正（最終益12%増額・最高益予想を上乗せ）と自社株買いを発表しており、その後3連騰していた。11月3日の米中間選挙で民主党が上下両院の過半数を確保する見通しとなり、AIデータセンターの増設計画に遅れ・規制が及ぶとの見方が広がった。前日の米市場はダウ1,569ドル高と反発する一方、フィラデルフィア半導体株指数は3%超下落。クアルコムの引け後決算と時間外安も重なり、5日は寄り付きから半導体・AI関連に売りが集中した。日経平均の押し下げ寄与度1位で単独約1,097円と、上位5銘柄合計約2,068円の過半を占めた。",
