        "biz": "CRMを軸としたクラウドサービスを自社開発・提供。主力はEC事業者向けCRM／MA「LTV-Lab」（26年3月期売上の7割超）で、ほかに自治体のふるさと納税寄附者向け「ふるさとLab」、小売の需給予測「LTV-Zaiko」、実店舗とECの顧客統合「LTV-Omni」を展開する。",
        "detail": "9月30日に名証ネクスト市場への新規上場が承認された。公募367,000株・売出333,000株（ドコモ・イノベーションファンド2号が保有全株を放出）、オーバーアロットメント上限105,000株で、仮条件550〜570円に対し10月26日に公開価格を上限の570円に決定。吸収額約4.5億円・想定時価総額13.9億円という超小型案件で、主幹事はＪトラストグローバル証券。11月5日の初値は9時43分に700円を付け公開価格を22.8%上回ったが、直後の725円が当日高値となり以降は終日売り優勢。後場13時40分に562円まで下げ、終値は575円と初値比17.9%安で初日を終えた。オファリングレシオ32.4%の需給の重さと、東証グロースに比べ投資家の関心が集まりにくい名証ネクスト上場という評価が初値後の値崩れにつながった。なお上場初日のため前日終値は存在せず、上記の騰落率は初値700円に対する比率。",
        "outlook": "業績は26年3月期が売上4.44億円（26.1%増）・経常1.47億円（81.5%増、利益率33.1%）と小粒ながら高収益で、27年3月期1Qも売上1.27億円・経常0.51億円と好調を維持。終値が公開価格をわずかに上回る水準で踏みとどまったことから、まず570円の公開価格が下値の目安。ただし開発の約84%を1社に外注する体制と流動性の低さは要警戒。"
